4	/// Judgment grade for a single note.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
6	pub enum Grade {
7	    PureMax,  // ±25ms
8	    Pure,     // ±50ms
9	    Far,      // ±100ms
10	    Lost,     // miss (>100ms or auto-expire at 120ms)
11	}
12	
13	/// Result of judging a note.
14	#[derive(Debug, Clone, Copy)]
15	pub struct JudgResult {
16	    pub grade: Grade,
17	    pub lane: u8,
18	    pub time_ms: Ms,
19	}
20	
21	/// Score state.
22	#[derive(Debug, Clone)]
23	pub struct ScoreState {
24	    pub pure_max: u32,
25	    pub pure: u32,
26	    pub far: u32,
27	    pub lost: u32,
28	    pub combo: u32,
29	    pub max_combo: u32,
30	    pub total_notes: u32,
31	}
