33	impl ScoreState {
34	    pub fn new(total_notes: u32) -> Self {
35	        Self {
36	            pure_max: 0,
37	            pure: 0,
38	            far: 0,
39	            lost: 0,
40	            combo: 0,
41	            max_combo: 0,
42	            total_notes,
43	        }
44	    }
45	
46	    pub fn record(&mut self, grade: Grade) {
47	        match grade {
48	            Grade::PureMax => {
49	                self.pure_max += 1;
50	                self.combo += 1;
51	            }
52	            Grade::Pure => {
53	                self.pure += 1;
54	                self.combo += 1;
55	            }
56	            Grade::Far => {
57	                self.far += 1;
58	                self.combo += 1;
59	            }
60	            Grade::Lost => {
61	                self.lost += 1;
62	                self.combo = 0;
63	            }
64	        }
65	        self.max_combo = self.max_combo.max(self.combo);
66	    }
67	
68	    /// Arcaea score formula: 10,000,000 / noteCount per note.
69	    /// Max: +scorePerNote+1, Pure: +scorePerNote, Far: +half, Lost: 0.
70	    pub fn score(&self) -> u64 {
71	        if self.total_notes == 0 {
72	            return 0;
73	        }
74	        let per = 10_000_000u64 / self.total_notes as u64;
75	        self.pure_max as u64 * (per + 1)
76	            + self.pure as u64 * per
77	            + self.far as u64 * (per / 2)
78	    }
