95	    end: Ms,
96	    lane: u8,
97	    locked: bool,      // true until initial tap unlock
98	    tick_times: Vec<Ms>, // judgment tick timings
99	    next_tick: usize,    // index of next tick to process
100	}
101	
102	pub(crate) const PURE_MAX_WINDOW: Ms = 25;
103	pub(crate) const PURE_WINDOW: Ms = 50;
104	pub(crate) const FAR_WINDOW: Ms = 100;
105	pub(crate) const MISS_EXPIRE: Ms = 120;
106	
107	/// Greedy judgment engine for tap, hold, and arctap notes.
108	pub struct GreedyJudge {
109	    pending_taps: Vec<PendingTap>,
110	    pending_holds: Vec<PendingHold>,
111	    /// ArcTap (sky note): same windows as tap, any lane matches (no positional input on desktop).
112	    pending_arctaps: Vec<PendingTap>,
113	    pub score: ScoreState,
114	    /// Recent judgment results for rendering feedback (drained by renderer).
115	    pub recent: Vec<JudgResult>,
116	}
117	
118	impl GreedyJudge {
119	    pub fn new(chart: &Chart) -> Self {
120	        let mut pending_taps = Vec::new();
121	        let mut pending_holds = Vec::new();
122	        let mut total_combo = 0u32;
123	
124	        for group in &chart.groups {
125	            // Taps: 1 combo each
126	            for tap in &group.taps {
127	                pending_taps.push(PendingTap {
128	                    time: tap.time,
129	                    lane: tap.lane as u8,
130	                    judged: false,
131	                });
132	                total_combo += 1;
133	            }
134	
135	            // Holds: calculate tick timings
136	            let base_bpm = group.timings.first().map(|t| t.bpm).unwrap_or(120.0);
137	            let density = chart.timing_point_density_factor;
138	
139	            for hold in &group.holds {
140	                let bpm = base_bpm.abs(); // TODO: use BPM at hold start time
141	                let duration = hold.end - hold.start;
142	                if duration <= 0 || bpm == 0.0 {
143	                    continue;
144	                }
145	
146	                let interval = if bpm >= 255.0 {
147	                    60_000.0 / bpm / density
148	                } else {
149	                    30_000.0 / bpm / density
150	                };
151	
152	                let count = (duration as f32 / interval) as i32;
153	                let mut tick_times = Vec::new();
154	
155	                if count <= 1 {
156	                    // Single tick at midpoint
157	                    tick_times.push(hold.start + duration / 2);
158	                } else {
159	                    // First tick at start + interval, then every interval
160	                    // Total combo = count - 1 (per ArcCreate)
161	                    for i in 1..count {
162	                        tick_times.push(hold.start + (i as f32 * interval) as i32);
163	                    }
164	                }
165	
166	                total_combo += tick_times.len() as u32;
167	
168	                pending_holds.push(PendingHold {
169	                    start: hold.start,
170	                    end: hold.end,
171	                    lane: hold.lane as u8,
172	                    locked: true,
173	                    tick_times,
174	                    next_tick: 0,
175	                });
176	            }
177	
178	            // ArcTaps (sky notes on trace arcs): same judgment as taps
179	            for arc in &group.arcs {
180	                if arc.is_trace {
181	                    for sn in &arc.sky_notes {
182	                        pending_taps.push(PendingTap {
183	                            time: sn.time,
184	                            lane: 0, // sentinel: matches any lane on desktop
185	                            judged: false,
186	                        });
187	                        total_combo += 1;
188	                    }
189	                }
190	            }
191	        }
192	
193	        // Separate arctaps (lane=0) from lane taps for matching priority
194	        let pending_arctaps: Vec<PendingTap> = pending_taps
195	            .iter()
196	            .filter(|p| p.lane == 0)
197	            .map(|p| PendingTap { time: p.time, lane: 0, judged: false })
198	            .collect();
199	        pending_taps.retain(|p| p.lane != 0);
200	
201	        pending_taps.sort_by_key(|p| p.time);
202	        pending_holds.sort_by_key(|p| p.start);
203	
204	        Self {
205	            pending_taps,
206	            pending_holds,
207	            pending_arctaps,
208	            score: ScoreState::new(total_combo),
209	            recent: Vec::new(),
210	        }
211	    }
212	
213	    /// Process inputs and advance time.
214	    /// `input_mgr` provides held-lane state for hold judgment.
215	    pub fn update(&mut self, current_time: Ms, inputs: &[InputEvent], input_mgr: &InputManager) {
216	        // 1. Match tap inputs to pending taps (greedy: closest time first)
217	        let mut consumed = vec![false; inputs.len()];
218	
219	        for (ii, input) in inputs.iter().enumerate() {
220	            let mut best_idx = None;
221	            let mut best_dt = Ms::MAX;
222	
223	            for (i, p) in self.pending_taps.iter().enumerate() {
224	                if p.judged || p.lane != input.lane {
225	                    continue;
226	                }
227	                let dt = (input.time_ms - p.time).abs();
228	                if dt <= FAR_WINDOW && dt < best_dt {
229	                    best_dt = dt;
230	                    best_idx = Some(i);
231	                }
232	            }
233	
234	            if let Some(idx) = best_idx {
235	                let grade = classify(best_dt);
236	                self.pending_taps[idx].judged = true;
237	                self.score.record(grade);
238	                self.recent.push(JudgResult {
239	                    grade,
240	                    lane: input.lane,
241	                    time_ms: input.time_ms,
242	                });
243	                consumed[ii] = true;
244	            }
245	        }
246	
247	        // 2. Unconsumed inputs try to unlock holds
248	        for (ii, input) in inputs.iter().enumerate() {
249	            if consumed[ii] {
250	                continue;
251	            }
252	            for hold in &mut self.pending_holds {
253	                if !hold.locked || hold.lane != input.lane {
254	                    continue;
255	                }
256	                // Hold unlock window: start ± MissExpire
257	                let dt = (input.time_ms - hold.start).abs();
258	                if dt <= MISS_EXPIRE {
259	                    hold.locked = false;
260	                    break;
261	                }
262	            }
263	        }
264	
265	        // 2b. Unconsumed inputs try to match arctaps (any lane)
266	        for (ii, input) in inputs.iter().enumerate() {
267	            if consumed[ii] {
268	                continue;
269	            }
270	            let mut best_idx = None;
271	            let mut best_dt = Ms::MAX;
272	            for (i, p) in self.pending_arctaps.iter().enumerate() {
273	                if p.judged {
274	                    continue;
275	                }
276	                let dt = (input.time_ms - p.time).abs();
277	                if dt <= FAR_WINDOW && dt < best_dt {
278	                    best_dt = dt;
279	                    best_idx = Some(i);
280	                }
281	            }
282	            if let Some(idx) = best_idx {
283	                let grade = classify(best_dt);
284	                self.pending_arctaps[idx].judged = true;
285	                self.score.record(grade);
286	                self.recent.push(JudgResult {
287	                    grade,
288	                    lane: input.lane,
289	                    time_ms: input.time_ms,
290	                });
291	                consumed[ii] = true;
292	            }
293	        }
294	
295	        // 3. Auto-miss expired taps and arctaps
296	        for p in self.pending_taps.iter_mut().chain(self.pending_arctaps.iter_mut()) {
297	            if p.judged {
298	                continue;
299	            }
300	            if p.time + MISS_EXPIRE < current_time {
301	                p.judged = true;
302	                self.score.record(Grade::Lost);
303	                self.recent.push(JudgResult {
304	                    grade: Grade::Lost,
305	                    lane: p.lane,
306	                    time_ms: p.time,
307	                });
308	            }
309	        }
310	
311	        // 4. Process hold ticks
312	        for hold in &mut self.pending_holds {
313	            // Auto-unlock holds whose tap window expired (auto-miss the tap portion)
314	            if hold.locked && hold.start + MISS_EXPIRE < current_time {
315	                hold.locked = false;
316	            }
317	
318	            while hold.next_tick < hold.tick_times.len() {
319	                let tick_time = hold.tick_times[hold.next_tick];
320	                if tick_time > current_time {
321	                    break; // not yet
322	                }
323	
324	                let held = input_mgr.is_held(hold.lane);
325	                let grade = if held && !hold.locked {
326	                    Grade::PureMax
327	                } else {
328	                    Grade::Lost
329	                };
330	                self.score.record(grade);
331	                self.recent.push(JudgResult {
332	                    grade,
333	                    lane: hold.lane,
334	                    time_ms: tick_time,
335	                });
336	                hold.next_tick += 1;
337	            }
338	        }
339	    }
340	
341	    /// Returns true if a tap at this time+lane has already been judged.
342	    pub fn is_judged(&self, time: Ms, lane: u8) -> bool {
343	        self.pending_taps
344	            .iter()
345	            .any(|p| p.time == time && p.lane == lane && p.judged)
346	    }
347	
348	    /// Returns true if an arctap (sky note) at this time has been judged.
349	    pub fn is_arctap_judged(&self, time: Ms) -> bool {
350	        self.pending_arctaps.iter().any(|p| p.time == time && p.judged)
351	    }
352	
353	    /// Returns true if a hold is active (unlocked and current time within range).
354	    pub fn is_hold_active(&self, start: Ms, lane: u8, current_time: Ms) -> bool {
355	        self.pending_holds.iter().any(|h| {
356	            h.start == start
357	                && h.lane == lane
358	                && !h.locked
359	                && current_time >= h.start
360	                && current_time <= h.end
361	        })
362	    }
363	}
364	
365	fn classify(abs_dt: Ms) -> Grade {
366	    if abs_dt <= PURE_MAX_WINDOW {
367	        Grade::PureMax
368	    } else if abs_dt <= PURE_WINDOW {
369	        Grade::Pure
370	    } else {
371	        Grade::Far
372	    }
373	}
