use crate::chart::types::{Chart, Ms};
use crate::input::{InputEvent, InputManager};

/// Judgment grade for a single note.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Grade {
    PureMax,  // ±25ms
    Pure,     // ±50ms
    Far,      // ±100ms
    Lost,     // miss (>100ms or auto-expire at 120ms)
}

/// Result of judging a note.
#[derive(Debug, Clone, Copy)]
pub struct JudgResult {
    pub grade: Grade,
    pub lane: u8,
    pub time_ms: Ms,
}

/// Score state.
#[derive(Debug, Clone)]
pub struct ScoreState {
    pub pure_max: u32,
    pub pure: u32,
    pub far: u32,
    pub lost: u32,
    pub combo: u32,
    pub max_combo: u32,
    pub total_notes: u32,
}

impl ScoreState {
    pub fn new(total_notes: u32) -> Self {
        Self {
            pure_max: 0,
            pure: 0,
            far: 0,
            lost: 0,
            combo: 0,
            max_combo: 0,
            total_notes,
        }
    }

    pub fn record(&mut self, grade: Grade) {
        match grade {
            Grade::PureMax => {
                self.pure_max += 1;
                self.combo += 1;
            }
            Grade::Pure => {
                self.pure += 1;
                self.combo += 1;
            }
            Grade::Far => {
                self.far += 1;
                self.combo += 1;
            }
            Grade::Lost => {
                self.lost += 1;
                self.combo = 0;
            }
        }
        self.max_combo = self.max_combo.max(self.combo);
    }

    /// Arcaea score formula: 10,000,000 / noteCount per note.
    /// Max: +scorePerNote+1, Pure: +scorePerNote, Far: +half, Lost: 0.
    pub fn score(&self) -> u64 {
        if self.total_notes == 0 {
            return 0;
        }
        let per = 10_000_000u64 / self.total_notes as u64;
        self.pure_max as u64 * (per + 1)
            + self.pure as u64 * per
            + self.far as u64 * (per / 2)
    }

    pub fn judged_count(&self) -> u32 {
        self.pure_max + self.pure + self.far + self.lost
    }
}

/// Pending tap note waiting for judgment.
struct PendingTap {
    time: Ms,
    lane: u8,
    judged: bool,
}

/// Pending hold note.
struct PendingHold {
    start: Ms,
    end: Ms,
    lane: u8,
    locked: bool,      // true until initial tap unlock
    tick_times: Vec<Ms>, // judgment tick timings
    next_tick: usize,    // index of next tick to process
}

pub(crate) const PURE_MAX_WINDOW: Ms = 25;
pub(crate) const PURE_WINDOW: Ms = 50;
pub(crate) const FAR_WINDOW: Ms = 100;
pub(crate) const MISS_EXPIRE: Ms = 120;

/// Greedy judgment engine for tap, hold, and arctap notes.
pub struct GreedyJudge {
    pending_taps: Vec<PendingTap>,
    pending_holds: Vec<PendingHold>,
    /// ArcTap (sky note): same windows as tap, any lane matches (no positional input on desktop).
    pending_arctaps: Vec<PendingTap>,
    pub score: ScoreState,
    /// Recent judgment results for rendering feedback (drained by renderer).
    pub recent: Vec<JudgResult>,
}

impl GreedyJudge {
    pub fn new(chart: &Chart) -> Self {
        let mut pending_taps = Vec::new();
        let mut pending_holds = Vec::new();
        let mut total_combo = 0u32;

        for group in &chart.groups {
            // Taps: 1 combo each
            for tap in &group.taps {
                pending_taps.push(PendingTap {
                    time: tap.time,
                    lane: tap.lane as u8,
                    judged: false,
                });
                total_combo += 1;
            }

            // Holds: calculate tick timings
            let base_bpm = group.timings.first().map(|t| t.bpm).unwrap_or(120.0);
            let density = chart.timing_point_density_factor;

            for hold in &group.holds {
                let bpm = base_bpm.abs(); // TODO: use BPM at hold start time
                let duration = hold.end - hold.start;
                if duration <= 0 || bpm == 0.0 {
                    continue;
                }

                let interval = if bpm >= 255.0 {
                    60_000.0 / bpm / density
                } else {
                    30_000.0 / bpm / density
                };

                let count = (duration as f32 / interval) as i32;
                let mut tick_times = Vec::new();

                if count <= 1 {
                    // Single tick at midpoint
                    tick_times.push(hold.start + duration / 2);
                } else {
                    // First tick at start + interval, then every interval
                    // Total combo = count - 1 (per ArcCreate)
                    for i in 1..count {
                        tick_times.push(hold.start + (i as f32 * interval) as i32);
                    }
                }

                total_combo += tick_times.len() as u32;

                pending_holds.push(PendingHold {
                    start: hold.start,
                    end: hold.end,
                    lane: hold.lane as u8,
                    locked: true,
                    tick_times,
                    next_tick: 0,
                });
            }

            // ArcTaps (sky notes on trace arcs): same judgment as taps
            for arc in &group.arcs {
                if arc.is_trace {
                    for sn in &arc.sky_notes {
                        pending_taps.push(PendingTap {
                            time: sn.time,
                            lane: 0, // sentinel: matches any lane on desktop
                            judged: false,
                        });
                        total_combo += 1;
                    }
                }
            }
        }

        // Separate arctaps (lane=0) from lane taps for matching priority
        let pending_arctaps: Vec<PendingTap> = pending_taps
            .iter()
            .filter(|p| p.lane == 0)
            .map(|p| PendingTap { time: p.time, lane: 0, judged: false })
            .collect();
        pending_taps.retain(|p| p.lane != 0);

        pending_taps.sort_by_key(|p| p.time);
        pending_holds.sort_by_key(|p| p.start);

        Self {
            pending_taps,
            pending_holds,
            pending_arctaps,
            score: ScoreState::new(total_combo),
            recent: Vec::new(),
        }
    }

    /// Process inputs and advance time.
    /// `input_mgr` provides held-lane state for hold judgment.
    pub fn update(&mut self, current_time: Ms, inputs: &[InputEvent], input_mgr: &InputManager) {
        // 1. Match tap inputs to pending taps (greedy: closest time first)
        let mut consumed = vec![false; inputs.len()];

        for (ii, input) in inputs.iter().enumerate() {
            let mut best_idx = None;
            let mut best_dt = Ms::MAX;

            for (i, p) in self.pending_taps.iter().enumerate() {
                if p.judged || p.lane != input.lane {
                    continue;
                }
                let dt = (input.time_ms - p.time).abs();
                if dt <= FAR_WINDOW && dt < best_dt {
                    best_dt = dt;
                    best_idx = Some(i);
                }
            }

            if let Some(idx) = best_idx {
                let grade = classify(best_dt);
                self.pending_taps[idx].judged = true;
                self.score.record(grade);
                self.recent.push(JudgResult {
                    grade,
                    lane: input.lane,
                    time_ms: input.time_ms,
                });
                consumed[ii] = true;
            }
        }

        // 2. Unconsumed inputs try to unlock holds
        for (ii, input) in inputs.iter().enumerate() {
            if consumed[ii] {
                continue;
            }
            for hold in &mut self.pending_holds {
                if !hold.locked || hold.lane != input.lane {
                    continue;
                }
                // Hold unlock window: start ± MissExpire
                let dt = (input.time_ms - hold.start).abs();
                if dt <= MISS_EXPIRE {
                    hold.locked = false;
                    break;
                }
            }
        }

        // 2b. Unconsumed inputs try to match arctaps (any lane)
        for (ii, input) in inputs.iter().enumerate() {
            if consumed[ii] {
                continue;
            }
            let mut best_idx = None;
            let mut best_dt = Ms::MAX;
            for (i, p) in self.pending_arctaps.iter().enumerate() {
                if p.judged {
                    continue;
                }
                let dt = (input.time_ms - p.time).abs();
                if dt <= FAR_WINDOW && dt < best_dt {
                    best_dt = dt;
                    best_idx = Some(i);
                }
            }
            if let Some(idx) = best_idx {
                let grade = classify(best_dt);
                self.pending_arctaps[idx].judged = true;
                self.score.record(grade);
                self.recent.push(JudgResult {
                    grade,
                    lane: input.lane,
                    time_ms: input.time_ms,
                });
                consumed[ii] = true;
            }
        }

        // 3. Auto-miss expired taps and arctaps
        for p in self.pending_taps.iter_mut().chain(self.pending_arctaps.iter_mut()) {
            if p.judged {
                continue;
            }
            if p.time + MISS_EXPIRE < current_time {
                p.judged = true;
                self.score.record(Grade::Lost);
                self.recent.push(JudgResult {
                    grade: Grade::Lost,
                    lane: p.lane,
                    time_ms: p.time,
                });
            }
        }

        // 4. Process hold ticks
        for hold in &mut self.pending_holds {
            // Auto-unlock holds whose tap window expired (auto-miss the tap portion)
            if hold.locked && hold.start + MISS_EXPIRE < current_time {
                hold.locked = false;
            }

            while hold.next_tick < hold.tick_times.len() {
                let tick_time = hold.tick_times[hold.next_tick];
                if tick_time > current_time {
                    break; // not yet
                }

                let held = input_mgr.is_held(hold.lane);
                let grade = if held && !hold.locked {
                    Grade::PureMax
                } else {
                    Grade::Lost
                };
                self.score.record(grade);
                self.recent.push(JudgResult {
                    grade,
                    lane: hold.lane,
                    time_ms: tick_time,
                });
                hold.next_tick += 1;
            }
        }
    }

    /// Returns true if a tap at this time+lane has already been judged.
    pub fn is_judged(&self, time: Ms, lane: u8) -> bool {
        self.pending_taps
            .iter()
            .any(|p| p.time == time && p.lane == lane && p.judged)
    }

    /// Returns true if an arctap (sky note) at this time has been judged.
    pub fn is_arctap_judged(&self, time: Ms) -> bool {
        self.pending_arctaps.iter().any(|p| p.time == time && p.judged)
    }

    /// Returns true if a hold is active (unlocked and current time within range).
    pub fn is_hold_active(&self, start: Ms, lane: u8, current_time: Ms) -> bool {
        self.pending_holds.iter().any(|h| {
            h.start == start
                && h.lane == lane
                && !h.locked
                && current_time >= h.start
                && current_time <= h.end
        })
    }
}

fn classify(abs_dt: Ms) -> Grade {
    if abs_dt <= PURE_MAX_WINDOW {
        Grade::PureMax
    } else if abs_dt <= PURE_WINDOW {
        Grade::Pure
    } else {
        Grade::Far
    }
}

