28	}
29	
30	impl AudioEngine {
31	    /// Load an ogg file and start playback after `delay_ms` of silence.
32	    pub fn play_ogg(path: &Path, delay_ms: i32) -> Result<Self, String> {
33	        let data = decode_ogg(path)?;
34	        Self::play(data, delay_ms)
35	    }
36	
37	    /// Start playback of decoded audio data.
38	    fn play(data: AudioData, delay_ms: i32) -> Result<Self, String> {
39	        let host = cpal::default_host();
40	        let device = host
41	            .default_output_device()
42	            .ok_or("no audio output device")?;
43	        let config = device
44	            .default_output_config()
45	            .map_err(|e| format!("no output config: {e}"))?;
46	
47	        log::info!(
48	            "Audio device: {:?}, format: {:?}",
49	            device.name().unwrap_or_default(),
50	            config,
51	        );
52	
53	        let output_rate = config.sample_rate().0;
54	        let output_channels = config.channels() as u16;
55	
56	        // Resample if needed (simple nearest-neighbor for now)
57	        let samples = if data.sample_rate != output_rate || data.channels != output_channels {
58	            resample(&data.samples, data.sample_rate, data.channels, output_rate, output_channels)
59	        } else {
60	            data.samples.clone()
61	        };
62	
63	        let total_samples = samples.len();
64	
65	        // Add leading silence for delay
66	        let delay_samples = (delay_ms as i64 * output_rate as i64 * output_channels as i64 / 1000) as usize;
67	
68	        // Shared playback position (in output samples, negative = delay)
69	        let position = Arc::new(AtomicI64::new(-(delay_samples as i64)));
70	        let pos_clone = position.clone();
71	
72	        let samples = Arc::new(samples);
73	        let samples_clone = samples.clone();
74	
75	        let stream = device
76	            .build_output_stream(
77	                &config.into(),
78	                move |output: &mut [f32], _: &cpal::OutputCallbackInfo| {
79	                    let mut pos = pos_clone.load(Ordering::Relaxed);
80	                    for frame in output.chunks_exact_mut(output_channels as usize) {
81	                        if pos < 0 {
82	                            // Leading silence
83	                            for s in frame.iter_mut() {
84	                                *s = 0.0;
85	                            }
86	                        } else {
87	                            let idx = pos as usize;
88	                            for (ch, s) in frame.iter_mut().enumerate() {
89	                                *s = samples_clone
90	                                    .get(idx + ch)
91	                                    .copied()
92	                                    .unwrap_or(0.0);
93	                            }
94	                        }
95	                        pos += output_channels as i64;
96	                    }
97	                    pos_clone.store(pos, Ordering::Relaxed);
98	                },
99	                |err| log::error!("audio stream error: {err}"),
100	                None,
101	            )
102	            .map_err(|e| format!("failed to build audio stream: {e}"))?;
103	
104	        stream.play().map_err(|e| format!("failed to start audio: {e}"))?;
105	
106	        log::info!(
107	            "Audio playing: {}Hz {}ch, {} samples ({:.1}s), delay {}ms",
108	            output_rate,
109	            output_channels,
110	            total_samples,
111	            total_samples as f32 / output_rate as f32 / output_channels as f32,
112	            delay_ms,
113	        );
114	
115	        Ok(Self {
116	            _stream: stream,
117	            position,
118	            sample_rate: output_rate,
119	            channels: output_channels,
120	            total_samples,
121	        })
122	    }
123	
124	    /// Current playback position in milliseconds.
125	    /// Negative values indicate lead-in silence.
126	    pub fn position_ms(&self) -> i32 {
127	        let pos = self.position.load(Ordering::Relaxed);
128	        (pos * 1000 / self.sample_rate as i64 / self.channels as i64) as i32
129	    }
130	
131	    /// Whether playback has finished.
132	    pub fn is_finished(&self) -> bool {
133	        let pos = self.position.load(Ordering::Relaxed);
134	        pos >= self.total_samples as i64
135	    }
136	}
137	
138	/// Decode an ogg/vorbis file to interleaved f32 samples.
139	fn decode_ogg(path: &Path) -> Result<AudioData, String> {
140	    let file = File::open(path).map_err(|e| format!("cannot open {}: {e}", path.display()))?;
141	    let mut reader = lewton::inside_ogg::OggStreamReader::new(file)
142	        .map_err(|e| format!("ogg parse error: {e}"))?;
143	
144	    let sample_rate = reader.ident_hdr.audio_sample_rate;
145	    let channels = reader.ident_hdr.audio_channels as u16;
146	
147	    let mut samples = Vec::new();
148	    while let Some(packet) = reader
149	        .read_dec_packet_itl()
150	        .map_err(|e| format!("vorbis decode error: {e}"))?
151	    {
152	        for &s in &packet {
153	            samples.push(s as f32 / 32768.0);
154	        }
155	    }
156	
157	    log::info!(
158	        "Decoded ogg: {}Hz {}ch, {} samples ({:.1}s)",
159	        sample_rate,
160	        channels,
161	        samples.len(),
162	        samples.len() as f32 / sample_rate as f32 / channels as f32,
163	    );
164	
165	    Ok(AudioData {
166	        samples,
167	        sample_rate,
168	        channels,
169	    })
170	}
171	
172	/// Simple nearest-neighbor resample + channel conversion.
173	fn resample(
174	    src: &[f32],
175	    src_rate: u32,
176	    src_ch: u16,
177	    dst_rate: u32,
178	    dst_ch: u16,
179	) -> Vec<f32> {
180	    let src_frames = src.len() / src_ch as usize;
181	    let dst_frames = (src_frames as u64 * dst_rate as u64 / src_rate as u64) as usize;
182	    let mut out = Vec::with_capacity(dst_frames * dst_ch as usize);
183	
184	    for i in 0..dst_frames {
185	        let src_frame = (i as u64 * src_rate as u64 / dst_rate as u64) as usize;
186	        for ch in 0..dst_ch as usize {
187	            let src_idx = src_frame * src_ch as usize + ch.min(src_ch as usize - 1);
188	            out.push(src.get(src_idx).copied().unwrap_or(0.0));
189	        }
190	    }
191	
192	    out
193	}
