//! Audio engine: low-latency playback with precise position tracking.
//!
//! Uses cpal for cross-platform output, lewton for ogg/vorbis decoding.
//! Audio position serves as the master clock for game timing.

use std::fs::File;
use std::path::Path;
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::Arc;

use cpal::traits::{DeviceTrait, HostTrait, StreamTrait};

/// Decoded audio samples (interleaved f32, stereo).
struct AudioData {
    samples: Vec<f32>,
    sample_rate: u32,
    channels: u16,
}

/// Audio engine with precise position tracking.
pub struct AudioEngine {
    _stream: cpal::Stream,
    /// Current playback position in samples (shared with audio thread).
    position: Arc<AtomicI64>,
    sample_rate: u32,
    channels: u16,
    total_samples: usize,
}

impl AudioEngine {
    /// Load an ogg file and start playback after `delay_ms` of silence.
    pub fn play_ogg(path: &Path, delay_ms: i32) -> Result<Self, String> {
        let data = decode_ogg(path)?;
        Self::play(data, delay_ms)
    }

    /// Start playback of decoded audio data.
    fn play(data: AudioData, delay_ms: i32) -> Result<Self, String> {
        let host = cpal::default_host();
        let device = host
            .default_output_device()
            .ok_or("no audio output device")?;
        let config = device
            .default_output_config()
            .map_err(|e| format!("no output config: {e}"))?;

        log::info!(
            "Audio device: {:?}, format: {:?}",
            device.name().unwrap_or_default(),
            config,
        );

        let output_rate = config.sample_rate().0;
        let output_channels = config.channels() as u16;

        // Resample if needed (simple nearest-neighbor for now)
        let samples = if data.sample_rate != output_rate || data.channels != output_channels {
            resample(&data.samples, data.sample_rate, data.channels, output_rate, output_channels)
        } else {
            data.samples.clone()
        };

        let total_samples = samples.len();

        // Add leading silence for delay
        let delay_samples = (delay_ms as i64 * output_rate as i64 * output_channels as i64 / 1000) as usize;

        // Shared playback position (in output samples, negative = delay)
        let position = Arc::new(AtomicI64::new(-(delay_samples as i64)));
        let pos_clone = position.clone();

        let samples = Arc::new(samples);
        let samples_clone = samples.clone();

        let stream = device
            .build_output_stream(
                &config.into(),
                move |output: &mut [f32], _: &cpal::OutputCallbackInfo| {
                    let mut pos = pos_clone.load(Ordering::Relaxed);
                    for frame in output.chunks_exact_mut(output_channels as usize) {
                        if pos < 0 {
                            // Leading silence
                            for s in frame.iter_mut() {
                                *s = 0.0;
                            }
                        } else {
                            let idx = pos as usize;
                            for (ch, s) in frame.iter_mut().enumerate() {
                                *s = samples_clone
                                    .get(idx + ch)
                                    .copied()
                                    .unwrap_or(0.0);
                            }
                        }
                        pos += output_channels as i64;
                    }
                    pos_clone.store(pos, Ordering::Relaxed);
                },
                |err| log::error!("audio stream error: {err}"),
                None,
            )
            .map_err(|e| format!("failed to build audio stream: {e}"))?;

        stream.play().map_err(|e| format!("failed to start audio: {e}"))?;

        log::info!(
            "Audio playing: {}Hz {}ch, {} samples ({:.1}s), delay {}ms",
            output_rate,
            output_channels,
            total_samples,
            total_samples as f32 / output_rate as f32 / output_channels as f32,
            delay_ms,
        );

        Ok(Self {
            _stream: stream,
            position,
            sample_rate: output_rate,
            channels: output_channels,
            total_samples,
        })
    }

    /// Current playback position in milliseconds.
    /// Negative values indicate lead-in silence.
    pub fn position_ms(&self) -> i32 {
        let pos = self.position.load(Ordering::Relaxed);
        (pos * 1000 / self.sample_rate as i64 / self.channels as i64) as i32
    }

    /// Whether playback has finished.
    pub fn is_finished(&self) -> bool {
        let pos = self.position.load(Ordering::Relaxed);
        pos >= self.total_samples as i64
    }
}

/// Decode an ogg/vorbis file to interleaved f32 samples.
fn decode_ogg(path: &Path) -> Result<AudioData, String> {
    let file = File::open(path).map_err(|e| format!("cannot open {}: {e}", path.display()))?;
    let mut reader = lewton::inside_ogg::OggStreamReader::new(file)
        .map_err(|e| format!("ogg parse error: {e}"))?;

    let sample_rate = reader.ident_hdr.audio_sample_rate;
    let channels = reader.ident_hdr.audio_channels as u16;

    let mut samples = Vec::new();
    while let Some(packet) = reader
        .read_dec_packet_itl()
        .map_err(|e| format!("vorbis decode error: {e}"))?
    {
        for &s in &packet {
            samples.push(s as f32 / 32768.0);
        }
    }

    log::info!(
        "Decoded ogg: {}Hz {}ch, {} samples ({:.1}s)",
        sample_rate,
        channels,
        samples.len(),
        samples.len() as f32 / sample_rate as f32 / channels as f32,
    );

    Ok(AudioData {
        samples,
        sample_rate,
        channels,
    })
}

/// Simple nearest-neighbor resample + channel conversion.
fn resample(
    src: &[f32],
    src_rate: u32,
    src_ch: u16,
    dst_rate: u32,
    dst_ch: u16,
) -> Vec<f32> {
    let src_frames = src.len() / src_ch as usize;
    let dst_frames = (src_frames as u64 * dst_rate as u64 / src_rate as u64) as usize;
    let mut out = Vec::with_capacity(dst_frames * dst_ch as usize);

    for i in 0..dst_frames {
        let src_frame = (i as u64 * src_rate as u64 / dst_rate as u64) as usize;
        for ch in 0..dst_ch as usize {
            let src_idx = src_frame * src_ch as usize + ch.min(src_ch as usize - 1);
            out.push(src.get(src_idx).copied().unwrap_or(0.0));
        }
    }

    out
}

