1	use std::path::Path;
2	use std::sync::Arc;
3	use wgpu::util::DeviceExt;
4	use winit::window::Window;
5	
6	use super::camera::{Camera, CameraUniform};
7	use super::texture;
8	use super::vertex::Vertex;
9	use crate::chart::types::{Chart, Ms};
10	use crate::timing::GameClock;
11	
12	const SHADER: &str = "
13	struct CameraUniform {
14	    view_proj: mat4x4<f32>,
15	};
16	
17	@group(0) @binding(0)
18	var<uniform> camera: CameraUniform;
19	
20	@group(1) @binding(0)
21	var tex: texture_2d<f32>;
22	@group(1) @binding(1)
23	var tex_sampler: sampler;
24	
25	struct VsIn {
26	    @location(0) position: vec3<f32>,
27	    @location(1) color: vec4<f32>,
28	    @location(2) uv: vec2<f32>,
29	};
30	
31	struct VsOut {
32	    @builtin(position) clip_position: vec4<f32>,
33	    @location(0) color: vec4<f32>,
34	    @location(1) uv: vec2<f32>,
35	};
36	
37	@vertex
38	fn vs_main(in: VsIn) -> VsOut {
39	    var out: VsOut;
40	    out.clip_position = camera.view_proj * vec4<f32>(in.position, 1.0);
41	    out.color = in.color;
42	    out.uv = in.uv;
43	    return out;
44	}
45	
46	@fragment
47	fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
48	    let tex_color = textureSample(tex, tex_sampler, in.uv);
49	    return tex_color * in.color;
50	}
51	";
52	
53	/// A GPU buffer pair for geometry.
54	struct MeshBuffer {
55	    vertex: wgpu::Buffer,
56	    index: wgpu::Buffer,
57	    index_count: u32,
58	}
59	
60	pub struct Gpu {
61	    surface: wgpu::Surface<'static>,
62	    device: wgpu::Device,
63	    queue: wgpu::Queue,
64	    config: wgpu::SurfaceConfiguration,
65	
66	    pipeline: wgpu::RenderPipeline,
67	    depth_view: wgpu::TextureView,
68	
69	    camera: Camera,
70	    camera_buffer: wgpu::Buffer,
71	    camera_bind_group: wgpu::BindGroup,
72	
73	    // Textures (bind group per texture)
74	    tex_white: wgpu::BindGroup,
75	    tex_track: wgpu::BindGroup,
76	    tex_divider: wgpu::BindGroup,
77	    tex_judgment: wgpu::BindGroup,
78	    tex_note: wgpu::BindGroup,
79	    tex_hold: wgpu::BindGroup,
80	    tex_arc_body: wgpu::BindGroup,
81	    tex_arc_cap: wgpu::BindGroup,
82	    tex_sky: wgpu::BindGroup,
83	    tex_lane_hit: wgpu::BindGroup,
84	    tex_hit_pure: wgpu::BindGroup,
85	    tex_hit_far: wgpu::BindGroup,
86	    tex_bgl: wgpu::BindGroupLayout,
87	
88	    // Static geometry
89	    track_surface: MeshBuffer,
90	    track_dividers: MeshBuffer,
91	    track_judgment: MeshBuffer,
92	
93	    // Dynamic geometry (rebuilt each frame)
94	    note_taps: MeshBuffer,
95	    note_holds: MeshBuffer,
96	    note_arcs: MeshBuffer,
97	    note_arc_caps: MeshBuffer,
98	    note_sky: MeshBuffer,
99	    fx_lane: MeshBuffer,
100	    fx_pure: MeshBuffer,
101	    fx_far: MeshBuffer,
102	}
103	
104	fn create_mesh_buffer(device: &wgpu::Device, verts: &[Vertex], idxs: &[u32], label: &str) -> MeshBuffer {
105	    let vertex = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
106	        label: Some(&format!("{label}_verts")),
107	        contents: bytemuck::cast_slice(verts),
108	        usage: wgpu::BufferUsages::VERTEX,
109	    });
110	    let index = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
111	        label: Some(&format!("{label}_idxs")),
112	        contents: bytemuck::cast_slice(idxs),
113	        usage: wgpu::BufferUsages::INDEX,
114	    });
115	    MeshBuffer {
116	        vertex,
117	        index,
118	        index_count: idxs.len() as u32,
119	    }
120	}
121	
122	fn create_dynamic_buffer(device: &wgpu::Device, label: &str) -> MeshBuffer {
123	    let vertex = device.create_buffer(&wgpu::BufferDescriptor {
124	        label: Some(&format!("{label}_verts")),
125	        size: (500 * 4 * std::mem::size_of::<Vertex>()) as u64,
126	        usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
127	        mapped_at_creation: false,
128	    });
129	    let index = device.create_buffer(&wgpu::BufferDescriptor {
130	        label: Some(&format!("{label}_idxs")),
131	        size: (500 * 6 * std::mem::size_of::<u32>()) as u64,
132	        usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
133	        mapped_at_creation: false,
134	    });
135	    MeshBuffer {
136	        vertex,
137	        index,
138	        index_count: 0,
139	    }
140	}
141	
142	impl Gpu {
143	    pub async fn new(window: Arc<Window>, assets_dir: &Path) -> Self {
144	        let size = window.inner_size();
145	
146	        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
147	            backends: wgpu::Backends::all(),
148	            ..Default::default()
149	        });
150	
151	        let surface = instance
152	            .create_surface(window)
153	            .expect("failed to create surface");
154	
155	        let adapter = instance
156	            .request_adapter(&wgpu::RequestAdapterOptions {
157	                power_preference: wgpu::PowerPreference::HighPerformance,
158	                compatible_surface: Some(&surface),
159	                force_fallback_adapter: false,
160	            })
161	            .await
162	            .expect("no suitable GPU adapter");
163	
164	        log::info!("GPU: {:?}", adapter.get_info());
165	
166	        let limits = if cfg!(target_os = "android") {
167	            wgpu::Limits::downlevel_defaults()
168	        } else {
169	            wgpu::Limits::default()
170	        }
171	        .using_resolution(adapter.limits());
172	
173	        let (device, queue) = adapter
174	            .request_device(
175	                &wgpu::DeviceDescriptor {
176	                    label: Some("better-arc"),
177	                    required_features: wgpu::Features::empty(),
178	                    required_limits: limits,
179	                    ..Default::default()
180	                },
181	                None,
182	            )
183	            .await
184	            .expect("failed to create device");
185	
186	        // Surface
187	        let caps = surface.get_capabilities(&adapter);
188	        let format = caps
189	            .formats
190	            .iter()
191	            .find(|f| f.is_srgb())
192	            .copied()
193	            .unwrap_or(caps.formats[0]);
194	
195	        let config = wgpu::SurfaceConfiguration {
196	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
197	            format,
198	            width: size.width.max(1),
199	            height: size.height.max(1),
200	            present_mode: wgpu::PresentMode::AutoVsync,
201	            alpha_mode: caps.alpha_modes[0],
202	            view_formats: vec![],
203	            desired_maximum_frame_latency: 2,
204	        };
205	        surface.configure(&device, &config);
206	
207	        // Shader
208	        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
209	            label: Some("shader"),
210	            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
211	        });
212	
213	        // Camera
214	        let aspect = config.width as f32 / config.height as f32;
215	        let camera = Camera::arcaea_default(aspect, config.height as f32);
216	        let camera_uniform = CameraUniform::from(&camera);
217	
218	        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
219	            label: Some("camera_uniform"),
220	            contents: bytemuck::cast_slice(&[camera_uniform]),
221	            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
222	        });
223	
224	        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
225	            label: Some("camera_bgl"),
226	            entries: &[wgpu::BindGroupLayoutEntry {
227	                binding: 0,
228	                visibility: wgpu::ShaderStages::VERTEX,
229	                ty: wgpu::BindingType::Buffer {
230	                    ty: wgpu::BufferBindingType::Uniform,
231	                    has_dynamic_offset: false,
232	                    min_binding_size: None,
233	                },
234	                count: None,
235	            }],
236	        });
237	
238	        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
239	            label: Some("camera_bg"),
240	            layout: &camera_bgl,
241	            entries: &[wgpu::BindGroupEntry {
242	                binding: 0,
243	                resource: camera_buffer.as_entire_binding(),
244	            }],
245	        });
246	
247	        // Textures
248	        let tex_bgl = texture::texture_bind_group_layout(&device);
249	        let tex_white = texture::white_texture(&device, &queue, &tex_bgl);
250	
251	        let extracted = assets_dir.join("extracted");
252	        let load = |name: &str, label: &str| -> wgpu::BindGroup {
253	            let path = extracted.join(name);
254	            if path.exists() {
255	                texture::load_texture(&device, &queue, &tex_bgl, &path, label)
256	            } else {
257	                log::warn!("{name} not found, using white fallback");
258	                texture::white_texture(&device, &queue, &tex_bgl)
259	            }
260	        };
261	
262	        let tex_track = load("track.png", "track");
263	        let tex_divider = load("track_lane_divider.png", "divider");
264	        let tex_judgment = load("track_critical_line.png", "judgment");
265	        let tex_note = load("note.png", "note");
266	        let tex_hold = load("note_hold.png", "note_hold");
267	        let tex_arc_body = load("arc_body.png", "arc_body");
268	        let tex_arc_cap = load("arc_cap.png", "arc_cap");
269	        let tex_sky = load("sfx_l_note.jpg", "sky_note");
270	        let tex_lane_hit = load("lane_hit.png", "lane_hit");
271	        let tex_hit_pure = load("hit_pure.png", "hit_pure");
272	        let tex_hit_far = load("hit_far.png", "hit_far");
273	
274	        // Pipeline (now with texture bind group)
275	        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
276	            label: Some("pipeline_layout"),
277	            bind_group_layouts: &[&camera_bgl, &tex_bgl],
278	            push_constant_ranges: &[],
279	        });
280	
281	        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
282	            label: Some("main"),
283	            layout: Some(&pipeline_layout),
284	            vertex: wgpu::VertexState {
285	                module: &shader,
286	                entry_point: Some("vs_main"),
287	                buffers: &[Vertex::layout()],
288	                compilation_options: Default::default(),
289	            },
290	            fragment: Some(wgpu::FragmentState {
