296	                    write_mask: wgpu::ColorWrites::ALL,
297	                })],
298	                compilation_options: Default::default(),
299	            }),
300	            primitive: wgpu::PrimitiveState {
301	                topology: wgpu::PrimitiveTopology::TriangleList,
302	                cull_mode: None,
303	                ..Default::default()
304	            },
305	            depth_stencil: Some(wgpu::DepthStencilState {
306	                format: wgpu::TextureFormat::Depth32Float,
307	                depth_write_enabled: true,
308	                depth_compare: wgpu::CompareFunction::Less,
309	                stencil: wgpu::StencilState::default(),
310	                bias: wgpu::DepthBiasState::default(),
311	            }),
312	            multisample: wgpu::MultisampleState::default(),
313	            multiview: None,
314	            cache: None,
315	        });
316	
317	        // Depth buffer
318	        let depth_view = create_depth_texture(&device, config.width, config.height);
319	
320	        // Static geometry
321	        let track_geo = super::track::build_track_geometry();
322	        let track_surface = create_mesh_buffer(&device, &track_geo.surface.0, &track_geo.surface.1, "track_surface");
323	        let track_dividers = create_mesh_buffer(&device, &track_geo.dividers.0, &track_geo.dividers.1, "track_dividers");
324	        let track_judgment = create_mesh_buffer(&device, &track_geo.judgment.0, &track_geo.judgment.1, "track_judgment");
