373	    /// Update note geometry for the current frame.
374	    pub fn update_notes(
375	        &mut self,
376	        chart: &Chart,
377	        clock: &GameClock,
378	        current_time: Ms,
379	        judge: &crate::judgment::GreedyJudge,
380	        hit_effects: &[super::track::HitEffect],
381	    ) {
382	        let geo = super::track::build_note_geometry(chart, clock, current_time, judge, hit_effects);
383	        self.upload_mesh(&geo.taps, "note_taps");
384	        self.upload_mesh(&geo.holds, "note_holds");
385	        self.upload_mesh(&geo.arcs, "note_arcs");
386	        self.upload_mesh(&geo.arc_caps, "note_arc_caps");
387	        self.upload_mesh(&geo.sky, "note_sky");
388	        self.upload_mesh(&geo.lane_hits, "fx_lane");
389	        self.upload_mesh(&geo.hit_pure, "fx_pure");
390	        self.upload_mesh(&geo.hit_far, "fx_far");
391	    }
392	
393	    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
394	        let (verts, idxs) = mesh;
395	        let buf = match which {
396	            "note_taps" => &mut self.note_taps,
397	            "note_holds" => &mut self.note_holds,
398	            "note_arcs" => &mut self.note_arcs,
399	            "note_arc_caps" => &mut self.note_arc_caps,
400	            "note_sky" => &mut self.note_sky,
401	            "fx_lane" => &mut self.fx_lane,
402	            "fx_pure" => &mut self.fx_pure,
403	            "fx_far" => &mut self.fx_far,
404	            _ => return,
405	        };
406	        buf.index_count = idxs.len() as u32;
407	
408	        if verts.is_empty() {
409	            return;
410	        }
411	
412	        let vert_bytes = bytemuck::cast_slice(verts);
413	        let idx_bytes = bytemuck::cast_slice(idxs);
414	
415	        if vert_bytes.len() as u64 > buf.vertex.size() {
416	            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
417	                label: Some(&format!("{which}_verts")),
418	                contents: vert_bytes,
419	                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
420	            });
421	        } else {
422	            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
423	        }
424	
425	        if idx_bytes.len() as u64 > buf.index.size() {
426	            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
427	                label: Some(&format!("{which}_idxs")),
428	                contents: idx_bytes,
429	                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
430	            });
431	        } else {
432	            self.queue.write_buffer(&buf.index, 0, idx_bytes);
433	        }
434	    }
