436	    pub fn resize(&mut self, width: u32, height: u32) {
437	        self.config.width = width;
438	        self.config.height = height;
439	        self.surface.configure(&self.device, &self.config);
440	        self.depth_view = create_depth_texture(&self.device, width, height);
441	
442	        self.camera.aspect = width as f32 / height as f32;
443	        self.camera.far = {
444	            let eye_z = height as f32 / 2.0 / (30.0_f32.to_radians().tan());
445	            eye_z + height as f32 * 0.5
446	        };
447	        let uniform = CameraUniform::from(&self.camera);
448	        self.queue
449	            .write_buffer(&self.camera_buffer, 0, bytemuck::cast_slice(&[uniform]));
450	    }
451	
452	    pub fn render(&self) {
453	        let output = match self.surface.get_current_texture() {
454	            Ok(t) => t,
455	            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
456	                self.surface.configure(&self.device, &self.config);
457	                return;
458	            }
459	            Err(e) => {
460	                log::error!("surface error: {e:?}");
461	                return;
462	            }
463	        };
464	
465	        let view = output
466	            .texture
467	            .create_view(&wgpu::TextureViewDescriptor::default());
468	
469	        let mut encoder = self
470	            .device
471	            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
472	                label: Some("frame"),
473	            });
474	
475	        self.encode_render_pass(&mut encoder, &view, &self.depth_view);
476	
477	        self.queue.submit(std::iter::once(encoder.finish()));
478	        output.present();
479	    }
480	
481	    /// Encode the full render pass into the given encoder.
482	    fn encode_render_pass(
483	        &self,
484	        encoder: &mut wgpu::CommandEncoder,
485	        color_view: &wgpu::TextureView,
486	        depth_view: &wgpu::TextureView,
487	    ) {
488	        {
489	            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
490	                label: Some("main"),
491	                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
492	                    view: color_view,
493	                    resolve_target: None,
494	                    ops: wgpu::Operations {
495	                        load: wgpu::LoadOp::Clear(wgpu::Color {
496	                            r: 0.02,
497	                            g: 0.02,
498	                            b: 0.06,
499	                            a: 1.0,
500	                        }),
501	                        store: wgpu::StoreOp::Store,
502	                    },
503	                })],
504	                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
505	                    view: depth_view,
506	                    depth_ops: Some(wgpu::Operations {
507	                        load: wgpu::LoadOp::Clear(1.0),
508	                        store: wgpu::StoreOp::Store,
509	                    }),
510	                    stencil_ops: None,
511	                }),
512	                ..Default::default()
513	            });
514	
515	            pass.set_pipeline(&self.pipeline);
516	            pass.set_bind_group(0, &self.camera_bind_group, &[]);
517	
518	            // 1. Track surface (track.png)
519	            pass.set_bind_group(1, &self.tex_track, &[]);
520	            self.draw_mesh(&mut pass, &self.track_surface);
521	
522	            // 2. Lane dividers (track_lane_divider.png)
523	            pass.set_bind_group(1, &self.tex_divider, &[]);
524	            self.draw_mesh(&mut pass, &self.track_dividers);
525	
526	            // 3. Judgment line (track_critical_line.png)
527	            pass.set_bind_group(1, &self.tex_judgment, &[]);
528	            self.draw_mesh(&mut pass, &self.track_judgment);
529	
530	            // 4. Arc bodies (arc_body.png)
531	            pass.set_bind_group(1, &self.tex_arc_body, &[]);
532	            self.draw_mesh(&mut pass, &self.note_arcs);
533	
534	            // 4b. Arc caps (arc_cap.png)
535	            pass.set_bind_group(1, &self.tex_arc_cap, &[]);
536	            self.draw_mesh(&mut pass, &self.note_arc_caps);
537	
538	            // 5. Tap notes (note.png)
539	            pass.set_bind_group(1, &self.tex_note, &[]);
540	            self.draw_mesh(&mut pass, &self.note_taps);
541	
542	            // 6. Hold notes (note_hold.png)
543	            pass.set_bind_group(1, &self.tex_hold, &[]);
544	            self.draw_mesh(&mut pass, &self.note_holds);
545	
546	            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
547	            pass.set_bind_group(1, &self.tex_white, &[]);
548	            self.draw_mesh(&mut pass, &self.note_sky);
549	
550	            // 8. Lane glow (lane_hit.png)
551	            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
552	            self.draw_mesh(&mut pass, &self.fx_lane);
553	
554	            // 9. Pure hit effect (hit_pure.png)
555	            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
556	            self.draw_mesh(&mut pass, &self.fx_pure);
557	
558	            // 10. Far hit effect (hit_far.png)
559	            pass.set_bind_group(1, &self.tex_hit_far, &[]);
560	            self.draw_mesh(&mut pass, &self.fx_far);
561	        }
562	    }
