564	    /// Capture the current frame to an RGBA image.
565	    ///
566	    /// Renders to an offscreen texture and reads back the pixels.
567	    /// Call `update_notes()` before this to set up the scene.
568	    pub fn capture_frame(&self) -> image::RgbaImage {
569	        let width = self.config.width;
570	        let height = self.config.height;
571	        let format = self.config.format;
572	
573	        // Offscreen render target
574	        let capture_tex = self.device.create_texture(&wgpu::TextureDescriptor {
575	            label: Some("capture"),
576	            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
577	            mip_level_count: 1,
578	            sample_count: 1,
579	            dimension: wgpu::TextureDimension::D2,
580	            format,
581	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
582	            view_formats: &[],
583	        });
584	        let capture_view = capture_tex.create_view(&wgpu::TextureViewDescriptor::default());
585	
586	        // Separate depth buffer for capture (same dimensions)
587	        let capture_depth = create_depth_texture(&self.device, width, height);
588	
589	        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
590	            label: Some("capture"),
591	        });
592	
593	        self.encode_render_pass(&mut encoder, &capture_view, &capture_depth);
594	
595	        // Copy texture to readback buffer
596	        let bytes_per_pixel = 4u32;
597	        let unpadded_bpr = width * bytes_per_pixel;
598	        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
599	        let padded_bpr = (unpadded_bpr + align - 1) / align * align;
600	
601	        let buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
602	            label: Some("capture_readback"),
603	            size: (padded_bpr * height) as u64,
604	            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
605	            mapped_at_creation: false,
606	        });
607	
608	        encoder.copy_texture_to_buffer(
609	            wgpu::ImageCopyTexture {
610	                texture: &capture_tex,
611	                mip_level: 0,
612	                origin: wgpu::Origin3d::ZERO,
613	                aspect: wgpu::TextureAspect::All,
614	            },
615	            wgpu::ImageCopyBuffer {
616	                buffer: &buffer,
617	                layout: wgpu::ImageDataLayout {
618	                    offset: 0,
619	                    bytes_per_row: Some(padded_bpr),
620	                    rows_per_image: Some(height),
621	                },
622	            },
623	            wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
624	        );
625	
626	        self.queue.submit(std::iter::once(encoder.finish()));
627	
628	        // Map buffer and read pixels
629	        let buffer_slice = buffer.slice(..);
630	        let (sender, receiver) = std::sync::mpsc::channel();
631	        buffer_slice.map_async(wgpu::MapMode::Read, move |result| {
632	            sender.send(result).unwrap();
633	        });
634	        self.device.poll(wgpu::Maintain::Wait);
635	        receiver.recv().unwrap().unwrap();
636	
637	        let data = buffer_slice.get_mapped_range();
638	        let mut pixels = Vec::with_capacity((width * height * 4) as usize);
639	        for chunk in data.chunks(padded_bpr as usize) {
640	            pixels.extend_from_slice(&chunk[..unpadded_bpr as usize]);
641	        }
642	        drop(data);
643	        buffer.unmap();
644	
645	        // BGRA -> RGBA conversion if needed
646	        let is_bgra = matches!(
647	            format,
648	            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb
649	        );
650	        if is_bgra {
651	            for pixel in pixels.chunks_exact_mut(4) {
652	                pixel.swap(0, 2);
653	            }
654	        }
655	
656	        image::RgbaImage::from_raw(width, height, pixels).expect("failed to create image from capture")
657	    }
658	
659	    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
660	        if mesh.index_count == 0 {
661	            return;
662	        }
663	        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
664	        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
665	        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
666	    }
667	}
668	
669	fn create_depth_texture(device: &wgpu::Device, width: u32, height: u32) -> wgpu::TextureView {
670	    let texture = device.create_texture(&wgpu::TextureDescriptor {
671	        label: Some("depth"),
672	        size: wgpu::Extent3d {
673	            width,
674	            height,
675	            depth_or_array_layers: 1,
676	        },
677	        mip_level_count: 1,
678	        sample_count: 1,
679	        dimension: wgpu::TextureDimension::D2,
680	        format: wgpu::TextureFormat::Depth32Float,
681	        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
682	        view_formats: &[],
683	    });
684	    texture.create_view(&wgpu::TextureViewDescriptor::default())
685	}
