use crate::chart::types::Ms;

/// A tap input event with lane and timestamp.
#[derive(Debug, Clone, Copy)]
pub struct InputEvent {
    pub lane: u8,     // 1-4
    pub time_ms: Ms,  // chart-time when input occurred
}

/// Collects keyboard/touch input and converts to lane-based events.
pub struct InputManager {
    /// Pending events this frame (drained by judgment engine).
    pending: Vec<InputEvent>,
    /// Currently held lanes (index 0 unused, 1-4 for lanes).
    held: [bool; 5],
}

impl InputManager {
    pub fn new() -> Self {
        Self {
            pending: Vec::new(),
            held: [false; 5],
        }
    }

    /// Record a key press for a lane at the given chart time.
    pub fn key_down(&mut self, lane: u8, time_ms: Ms) {
        if (1..=4).contains(&lane) {
            self.pending.push(InputEvent { lane, time_ms });
            self.held[lane as usize] = true;
        }
    }

    /// Record a key release for a lane.
    pub fn key_up(&mut self, lane: u8) {
        if (1..=4).contains(&lane) {
            self.held[lane as usize] = false;
        }
    }

    /// Check if a lane is currently held.
    pub fn is_held(&self, lane: u8) -> bool {
        self.held.get(lane as usize).copied().unwrap_or(false)
    }

    /// Drain all pending events (called by judgment engine each frame).
    pub fn drain(&mut self) -> Vec<InputEvent> {
        std::mem::take(&mut self.pending)
    }
}

/// Map physical key code to lane number (1-4), or None.
/// Uses physical keys (immune to IME / keyboard layout).
/// Layout: A=Lane1, S=Lane2, D=Lane3, F=Lane4.
pub fn physical_key_to_lane(key: &winit::keyboard::PhysicalKey) -> Option<u8> {
    use winit::keyboard::{KeyCode, PhysicalKey};
    match key {
        PhysicalKey::Code(KeyCode::KeyA) => Some(1),
        PhysicalKey::Code(KeyCode::KeyS) => Some(2),
        PhysicalKey::Code(KeyCode::KeyD) => Some(3),
        PhysicalKey::Code(KeyCode::KeyF) => Some(4),
        _ => None,
    }
}

